document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll("h1, h2:not(.outil-title)");if("IntersectionObserver"in window){const t=new IntersectionObserver((e,o)=>{e.forEach((e,t)=>{e.isIntersecting&&(e.target.classList.add("visible"),o.unobserve(e.target))})},{threshold:.01,rootMargin:"0px 0px -20% 0px"});e.forEach(e=>t.observe(e))}else e.forEach(e=>e.classList.add("visible"))}),console.log("👋 Hello dev ! Tu regardes sous le capot ? Bienvenue dans l’atelier.");